## 📋 完整修复代码

```js
const bcrypt = require('bcrypt');
const { body, validationResult } = require('express-validator');
const rateLimit = require('express-rate-limit');

const loginLimiter = rateLimit({ windowMs: 15 * 60 * 1000, max: 5 });

app.post('/login',
  loginLimiter,
  body('username').isString().trim().isLength({ min: 1, max: 64 }),
  body('password').isString().isLength({ min: 1, max: 128 }),
  async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).send('Invalid input');

    const { username, password } = req.body;

    try {
      const [rows] = await db.promise().query(
        'SELECT id, pwd_hash FROM users WHERE name = ?',
        [username]
      );

      if (rows.length && await bcrypt.compare(password, rows[0].pwd_hash)) {
        req.session.userId = rows[0].id;
        res.send('ok');
      } else {
        // 统一提示，不区分"用户不存在"和"密码错误"（防枚举）
        res.status(401).send('用户名或密码错误');
      }
    } catch (err) {
      console.error('Login error:', err);
      res.status(500).send('服务器错误');
    }
  }
);
```

---

> **总结：原始代码 6 行，至少 6 个安全漏洞。** 其中 SQL 注入 + 明文密码 + 可伪造 Cookie 三者叠加，攻击者无需知道任何密码即可以任意身份登录，危害等级 **极高**。

